        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and band gaps introduced a powerful way to control light, with lasting consequences for optics and photonics.",
        "attribution": "Yablonovitch and John independently established the central concept, while Joannopoulos made foundational theoretical contributions that clarified and developed the field.",
        "maturity": "The effect is well established experimentally and has supported decades of research and applications.",
        "uncertainties": [
          "The relative weight of the independent early proposals and the subsequent theoretical development requires careful attribution."
        ]
      }
    },
